        uint256 ethAmount = 0.1 ether;

        // Give attacker more tokens if needed
        if (IShibaMoon(TARGET).balanceOf(attacker) < tokenAmount) {
            vm.prank(owner);
            IShibaMoon(TARGET).transfer(attacker, tokenAmount);
